1	"use client";
2	
3	import React from "react";
4	import { motion } from "framer-motion";
5	import { ArrowRight, PlayCircle } from "lucide-react";
6	import { BRAND, FONT, SHADOW, GRADIENT, fadeUp, stagger } from "@/lib/brand";
7	import { MangomintBlobs } from "@/components/brand/mangomint-blobs";
8	import { SectionEyebrow } from "@/components/shared/section-eyebrow";
9	import type { AccentKey } from "@/lib/brand";
10	
11	interface HeroSectionProps {
12	  eyebrow: string;
13	  eyebrowAccent?: AccentKey;
14	  headline: string;
15	  italicWord?: string;
16	  subhead: string;
17	  primaryCTA: { label: string; href: string };
18	  secondaryCTA?: { label: string; href: string; icon?: "play" };
19	  trustStats?: Array<{ stat: string; label: string }>;
20	  variant?: "default" | "centered" | "dark";
21	  showBlobs?: boolean;
22	}
23	
24	export function HeroSection({
25	  eyebrow,
26	  eyebrowAccent = "rust",
27	  headline,
28	  italicWord,
29	  subhead,
30	  primaryCTA,
31	  secondaryCTA,
32	  trustStats,
33	  variant = "default",
34	  showBlobs = true,
35	}: HeroSectionProps) {
36	  const isDark = variant === "dark";
37	  const isCentered = variant === "centered" || isDark;
38	
39	  function renderHeadline() {
40	    if (!italicWord || !headline.includes(italicWord)) {
41	      return headline;
42	    }
43	    const parts = headline.split(italicWord);
44	    return (
45	      <>
46	        {parts[0]}
47	        <em
48	          style={{
49	            fontStyle: "italic",
50	            color: isDark ? BRAND.rustBright : BRAND.rust,
51	          } as React.CSSProperties}
52	        >
53	          {italicWord}
54	        </em>
55	        {parts[1]}
56	      </>
57	    );
58	  }
59	
60	  return (
61	    <section
62	      style={{
63	        background: isDark ? BRAND.onyx : BRAND.bone,
64	        position: "relative",
65	        overflow: "hidden",
66	        paddingTop: 100,
67	        paddingBottom: 80,
68	      } as React.CSSProperties}
69	    >
70	      {showBlobs && <MangomintBlobs variant={isDark ? "cta" : "hero"} />}
71	
72	      {isDark && (
73	        <>
74	          <div
75	            aria-hidden="true"
76	            style={{
77	              position: "absolute",
78	              top: "20%",
79	              left: "10%",
80	              width: 600,
81	              height: 600,
82	              background: `radial-gradient(circle, rgba(200,53,31,0.20) 0%, transparent 65%)`,
83	              filter: "blur(80px)",
84	              pointerEvents: "none",
85	            } as React.CSSProperties}
86	          />
87	          <div
88	            aria-hidden="true"
89	            style={{
90	              position: "absolute",
91	              bottom: "10%",
92	              right: "10%",
93	              width: 500,
94	              height: 500,
95	              background: `radial-gradient(circle, rgba(200,53,31,0.15) 0%, transparent 65%)`,
96	              filter: "blur(80px)",
97	              pointerEvents: "none",
98	            } as React.CSSProperties}
99	          />
100	        </>
101	      )}
102	
103	      {!isDark && (
104	        <>
105	          <div
106	            aria-hidden="true"
107	            style={{
108	              position: "absolute",
109	              inset: 0,
110	              background: GRADIENT.heroBloom,
111	              pointerEvents: "none",
112	            } as React.CSSProperties}
113	          />
114	          <div
115	            aria-hidden="true"
116	            style={{
117	              position: "absolute",
118	              inset: 0,
119	              opacity: 0.25,
120	              backgroundImage: `linear-gradient(${BRAND.border} 1px, transparent 1px), linear-gradient(90deg, ${BRAND.border} 1px, transparent 1px)`,
121	              backgroundSize: "64px 64px",
122	              maskImage:
123	                "radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%)",
124	              WebkitMaskImage:
125	                "radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%)",
126	              pointerEvents: "none",
127	            } as React.CSSProperties}
128	          />
129	        </>
130	      )}
131	
132	      <div
133	        style={{
134	          maxWidth: 1280,
135	          margin: "0 auto",
136	          padding: "0 32px",
137	          position: "relative",
138	          zIndex: 2,
139	          display: "flex",
140	          flexDirection: "column",
141	          alignItems: isCentered ? "center" : "flex-start",
142	          textAlign: isCentered ? "center" : "left",
143	        } as React.CSSProperties}
144	      >
145	        <motion.div
146	          initial={{ opacity: 0, y: 8 }}
147	          animate={{ opacity: 1, y: 0 }}
148	          transition={{ duration: 0.6 }}
149	        >
150	          <SectionEyebrow
151	            label={eyebrow}
152	            accent={eyebrowAccent}
153	            dark={isDark}
154	          />
155	        </motion.div>
156	
157	        <motion.h1
158	          initial={{ opacity: 0, y: 24 }}
159	          animate={{ opacity: 1, y: 0 }}
160	          transition={{ duration: 0.8, ease: [0.22, 1, 0.36, 1] }}
161	          style={{
162	            fontFamily: FONT.serif,
163	            fontSize: "clamp(48px, 7vw, 96px)",
164	            lineHeight: 1.0,
165	            letterSpacing: "-0.03em",
166	            color: isDark ? BRAND.bone : BRAND.onyx,
167	            fontWeight: 400,
168	            maxWidth: 920,
169	            marginBottom: 24,
170	          } as React.CSSProperties}
171	        >
172	          {renderHeadline()}
173	        </motion.h1>
174	
175	        <motion.p
176	          initial={{ opacity: 0, y: 16 }}
177	          animate={{ opacity: 1, y: 0 }}
178	          transition={{ duration: 0.7, delay: 0.15 }}
179	          style={{
180	            fontFamily: FONT.sans,
181	            fontSize: 19,
182	            fontWeight: 400,
183	            lineHeight: 1.55,
184	            color: isDark ? BRAND.stoneLight : BRAND.stoneDark,
185	            maxWidth: 620,
186	            marginBottom: 36,
187	          } as React.CSSProperties}
188	        >
189	          {subhead}
190	        </motion.p>
191	
192	        <motion.div
193	          initial={{ opacity: 0, y: 12 }}
194	          animate={{ opacity: 1, y: 0 }}
195	          transition={{ duration: 0.6, delay: 0.3 }}
196	          style={{
197	            display: "flex",
198	            alignItems: "center",
199	            gap: 12,
200	            flexWrap: "wrap",
201	            marginBottom: trustStats ? 56 : 64,
202	            justifyContent: isCentered ? "center" : "flex-start",
203	          } as React.CSSProperties}
204	        >
205	          <a
206	            href={primaryCTA.href}
207	            style={{
208	              display: "inline-flex",
209	              alignItems: "center",
210	              gap: 8,
211	              background: isDark ? BRAND.bone : BRAND.onyx,
212	              color: isDark ? BRAND.onyx : BRAND.bone,
213	              fontFamily: FONT.sans,
214	              fontSize: 15,
215	              fontWeight: 500,
216	              padding: "14px 26px",
217	              borderRadius: 100,
218	              textDecoration: "none",
219	              boxShadow: SHADOW.soft,
220	            } as React.CSSProperties}
221	          >
222	            {primaryCTA.label}
223	            <ArrowRight size={15} />
224	          </a>
225	
226	          {secondaryCTA && (
227	            <a
228	              href={secondaryCTA.href}
229	              style={{
230	                display: "inline-flex",
231	                alignItems: "center",
232	                gap: 8,
233	                color: isDark ? BRAND.stoneLight : BRAND.stoneDark,
234	                fontFamily: FONT.sans,
235	                fontSize: 15,
236	                fontWeight: 500,
237	                textDecoration: "none",
238	                padding: "14px 20px",
239	                borderRadius: 100,
240	                border: isDark
241	                  ? `1.5px solid ${BRAND.borderInk}`
242	                  : `1px solid ${BRAND.border}`,
243	                background: isDark ? "transparent" : BRAND.white,
244	                boxShadow: isDark ? "none" : SHADOW.soft,
245	              } as React.CSSProperties}
246	            >
247	              {secondaryCTA.icon === "play" && (
248	                <PlayCircle size={15} strokeWidth={1.8} />
249	              )}
250	              {secondaryCTA.label}
251	            </a>
252	          )}
253	        </motion.div>
254	
255	        {trustStats && (
256	          <motion.div
257	            initial={{ opacity: 0 }}
258	            animate={{ opacity: 1 }}
259	            transition={{ duration: 0.7, delay: 0.6 }}
260	            variants={stagger}
261	            style={{
262	              marginTop: 64,
263	              paddingTop: 28,
264	              borderTop: `1px solid ${isDark ? "rgba(247,247,245,0.12)" : BRAND.border}`,
265	              display: "grid",
266	              gridTemplateColumns: `repeat(${trustStats.length}, 1fr)`,
267	              gap: 32,
268	              width: "100%",
269	            } as React.CSSProperties}
270	            className="v4-hero-trust"
271	          >
272	            {trustStats.map((s, i) => (
273	              <div key={i}>
274	                <div
275	                  style={{
276	                    fontFamily: FONT.sans,
277	                    fontSize: 18,
278	                    fontWeight: 600,
279	                    color: isDark ? BRAND.bone : BRAND.onyx,
280	                    letterSpacing: "-0.01em",
281	                    marginBottom: 4,
282	                  } as React.CSSProperties}
283	                >
284	                  {s.stat}
285	                </div>
286	                <div
287	                  style={{
288	                    fontFamily: FONT.sans,
289	                    fontSize: 13,
290	                    fontWeight: 400,
291	                    color: isDark ? BRAND.stoneLight : BRAND.stone,
292	                  } as React.CSSProperties}
293	                >
294	                  {s.label}
295	                </div>
296	              </div>
297	            ))}
298	          </motion.div>
299	        )}
300	      </div>
301	    </section>
302	  );
303	}
