68	
69	        {/* Gradient vignette */}
70	        <div
71	          aria-hidden="true"
72	          style={{
73	            position: "absolute",
74	            inset: 0,
75	            background:
76	              "linear-gradient(180deg, transparent 40%, rgba(15,15,15,0.45) 100%)",
77	          } as React.CSSProperties}
78	        />
79	
80	        {/* Serif initials */}
81	        <div
82	          style={{
83	            position: "absolute",
84	            top: "50%",
85	            left: "50%",
86	            transform: "translate(-50%, -58%)",
87	            fontFamily: FONT.serif,
88	            fontSize: 56,
89	            fontWeight: 400,
90	            color: "rgba(247,247,245,0.25)",
91	            letterSpacing: "-0.02em",
92	            userSelect: "none",
93	          } as React.CSSProperties}
94	        >
95	          {initials}
96	        </div>
97	
98	        {/* City badge */}
99	        <div
100	          style={{
101	            position: "absolute",
102	            bottom: 12,
