106	            gap: 5,
107	            padding: "4px 10px",
108	            borderRadius: 100,
109	            background: "rgba(247,247,245,0.18)",
110	            backdropFilter: "blur(6px)",
111	            fontFamily: FONT.sans,
112	            fontSize: 11,
113	            fontWeight: 500,
114	            color: BRAND.bone,
115	          } as React.CSSProperties}
116	        >
117	          <MapPin size={10} strokeWidth={2} color={BRAND.bone} />
118	          {city}
119	        </div>
120	
121	        {/* Index badge */}
122	        {index !== undefined && (
123	          <div
124	            style={{
125	              position: "absolute",
