190	      >
191	        {stats.map((stat, i) => (
192	          <div
193	            key={i}
194	            style={{
195	              padding: "12px 14px",
196	              borderRight:
197	                i < stats.length - 1
198	                  ? `1px solid ${BRAND.borderSoft}`
199	                  : "none",
200	              display: "flex",
201	              flexDirection: "column",
202	              gap: 3,
203	            } as React.CSSProperties}
204	          >
205	            <span
206	              style={{
207	                fontFamily: FONT.mono,
