216	            <span
217	              style={{
218	                fontFamily: FONT.sans,
219	                fontSize: 10,
220	                color: BRAND.stoneLight,
221	                lineHeight: 1.3,
222	              } as React.CSSProperties}
223	            >
224	              {stat.l}
225	            </span>
226	          </div>
227	        ))}
228	      </div>
229	    </motion.div>
230	  );
