1	import React from "react";
2	import { BRAND, FONT } from "@/lib/brand";
3	
4	interface StatStripItem {
5	  stat: string;
6	  label: string;
7	}
8	
9	interface StatStripProps {
10	  items: StatStripItem[];
11	  variant?: "default" | "dark";
12	  bordered?: boolean;
13	}
14	
15	export function StatStrip({
16	  items,
17	  variant = "default",
18	  bordered = true,
19	}: StatStripProps) {
20	  const isDark = variant === "dark";
21	  const borderColor = isDark ? "rgba(247,247,245,0.12)" : BRAND.border;
22	
23	  return (
24	    <div
25	      style={{
26	        padding: "28px 0",
27	        display: "grid",
28	        gridTemplateColumns: `repeat(${items.length}, 1fr)`,
29	        gap: 32,
