            style={{
              maxWidth: 1120,
              margin: "0 auto",
              padding: "0 32px",
            } as React.CSSProperties}
          >
            <StatStrip
              items={[
                { stat: "14 days", label: "average migration" },
                { stat: "100%", label: "data carried" },
                { stat: "$0", label: "until cutover" },
                { stat: "Zero", label: "downtime" },
